<script setup lang="ts">import{ref}from'vue';import PageHeader from'../../components/PageHeader.vue';const tab=ref('消息');const conversations=[{name:'主播小鹿',text:'预约已经确认，晚上见～',time:'10:28',unread:2},{name:'平台通知',text:'你的动态已审核通过',time:'昨天',unread:0}];const appointments=[{name:'主播一一',time:'明天 20:00',status:'已确认'},{name:'主播姜姜',time:'10月26日 19:30',status:'待确认'}];</script><template><main class="page business-page"><PageHeader title="消息与预约"/><div class="segmented"><button :class="{active:tab==='消息'}" @click="tab='消息'">消息</button><button :class="{active:tab==='预约'}" @click="tab='预约'">预约</button></div><section v-if="tab==='消息'" class="list-panel conversation-list"><article v-for="item in conversations" :key="item.name"><div class="mini-avatar">{{item.name[2]}}</div><div><b>{{item.name}}</b><small>{{item.text}}</small></div><aside><time>{{item.time}}</time><em v-if="item.unread">{{item.unread}}</em></aside></article></section><section v-else class="list-panel"><article v-for="item in appointments" :key="item.time" class="order-row"><div><b>{{item.name}}</b><small>{{item.time}}</small></div><span class="status-chip">{{item.status}}</span></article></section></main></template>
